pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let step_ratio = step_index as f64 / total_jobs as f64;
    let dynamic_horizon_factor = 1.0 + 2.0 * step_ratio * (1.0 - step_ratio);

    let next_job_fit_cpu = node_residual_cpu >= next_job_cpu;
    let next_job_fit_ram = node_residual_ram >= next_job_ram;

    let lookahead_penalty = if next_job_fit_cpu && next_job_fit_ram {
        0.0
    } else if next_job_fit_cpu || next_job_fit_ram {
        1.0
    } else {
        2.0
    };

    let score = cpu_norm + ram_norm - imbalance_penalty + dynamic_horizon_factor * lookahead_penalty;

    let step_factor = step_index as f64 / total_jobs as f64;
    let lookahead_factor = if next_job_cpu + job_cpu <= node_residual_cpu && next_job_ram + job_ram <= node_residual_ram {
        0.5
    } else {
        1.0
    };

    let score = score * 0.70 + ((cpu_norm + ram_norm + imbalance_penalty * step_factor * lookahead_factor) as f64) * 0.30;

    // Introduce non-linear conditionals and lookahead packing bonuses
    let cpu_bonus = if next_job_cpu <= node_residual_cpu / 2 { 1.5 } else { 1.0 };
    let ram_bonus = if next_job_ram <= node_residual_ram / 2 { 1.5 } else { 1.0 };

    // Introduce imbalance penalties
    let imbalance_factor = (cpu_norm - ram_norm).powi(2);

    score * cpu_bonus * ram_bonus * (1.0 + imbalance_factor) * lookahead_factor
}

