    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let step_factor = step_index as f64 / total_jobs as f64;

    // Lookahead packing bonuses
    let lookahead_cpu_bonus = if next_job_cpu + job_cpu <= node_residual_cpu { 0.25 * ((node_residual_cpu - (next_job_cpu + job_cpu)) as f64 / node_capacity_cpu as f64) } else { 0.0 };
