    let ram_fit_ratio = node_residual_ram as f64 / node_capacity_ram as f64;
    let fine_grained_fit_score = (cpu_fit_ratio * ram_fit_ratio).powf(2.0); // Non-linear combining of fit ratios

    // Combine residual fitting with lookahead anticipation
    let pack_bonus = ((node_capacity_cpu - node_residual_cpu) * (node_capacity_ram - node_residual_ram)) as f64 / (node_capacity_cpu * node_capacity_ram);

    // Final score calculation
    let score = fine_grained_fit_score + pack_bonus + lookahead_bonus - imbalance_penalty * step_factor;
    score
}

